/**
 * Hide category overview pages from autogenerated sidebar children and sort
 * sibling docs A–Z by frontmatter title (export / type name).
 */
import {readFileSync, readdirSync, writeFileSync} from 'node:fs';
import {join, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const TARGET_DIRS = [
  join(root, 'docs/reference/api'),
  join(root, 'docs/reference/types'),
];

function parseFrontmatter(content) {
  const normalized = content.replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
  if (!normalized.startsWith('---\n')) return null;
  const end = normalized.indexOf('\n---\n', 4);
  if (end === -1) return null;
  const raw = normalized.slice(4, end);
  const body = normalized.slice(end + 5);
  const fields = {};
  for (const line of raw.split('\n')) {
    const m = line.match(/^(\w+):\s*(.*)$/);
    if (!m) continue;
    let value = m[2].trim();
    if (
      (value.startsWith("'") && value.endsWith("'")) ||
      (value.startsWith('"') && value.endsWith('"'))
    ) {
      value = value.slice(1, -1);
    }
    fields[m[1]] = value;
  }
  return {fields, body, raw};
}

function serializeFrontmatter(fields) {
  const lines = ['---'];
  const order = [
    'title',
    'slug',
    'sidebar_label',
    'sidebar_position',
    'unlisted',
    'sidebar_class_name',
  ];
  const seen = new Set();
  for (const key of order) {
    if (key in fields) {
      seen.add(key);
      lines.push(formatField(key, fields[key]));
    }
  }
  for (const [key, value] of Object.entries(fields)) {
    if (!seen.has(key)) lines.push(formatField(key, value));
  }
  lines.push('---', '');
  return lines.join('\n');
}

function formatField(key, value) {
  if (value === true || value === 'true') return `${key}: true`;
  if (value === false || value === 'false') return `${key}: false`;
  if (/^[A-Za-z0-9_]+$/.test(String(value))) return `${key}: ${value}`;
  return `${key}: '${String(value).replace(/'/g, "''")}'`;
}

function processDirectory(dir) {
  const entries = readdirSync(dir, {withFileTypes: true});
  const mdxFiles = entries.filter((e) => e.isFile() && e.name.endsWith('.mdx'));
  if (mdxFiles.length === 0) return {index: 0, sorted: 0};

  let indexUpdated = 0;
  let sortedUpdated = 0;

  const indexFile = mdxFiles.find((e) => e.name === 'index.mdx');
  if (indexFile) {
    const path = join(dir, indexFile.name);
    const parsed = parseFrontmatter(readFileSync(path, 'utf8'));
    if (parsed) {
      const next = {...parsed.fields};
      next.unlisted = true;
      delete next.sidebar_position;
      const content = serializeFrontmatter(next) + parsed.body;
      writeFileSync(path, content);
      indexUpdated++;
    }
  }

  const docFiles = mdxFiles
    .filter((e) => e.name !== 'index.mdx')
    .map((e) => {
      const path = join(dir, e.name);
      const parsed = parseFrontmatter(readFileSync(path, 'utf8'));
      const title = parsed?.fields.title ?? e.name.replace(/\.mdx$/, '');
      return {path, parsed, title};
    })
    .filter((f) => f.parsed)
    .sort((a, b) => a.title.localeCompare(b.title, 'en', {sensitivity: 'base'}));

  docFiles.forEach((file, i) => {
    const position = String(i + 1);
    const next = {...file.parsed.fields, sidebar_position: position};
    const content = serializeFrontmatter(next) + file.parsed.body;
    writeFileSync(file.path, content);
    sortedUpdated++;
  });

  return {index: indexUpdated, sorted: sortedUpdated};
}

let totalIndex = 0;
let totalSorted = 0;

for (const base of TARGET_DIRS) {
  if (base.endsWith('/api') || base.endsWith('\\api')) {
    for (const cat of readdirSync(base, {withFileTypes: true}).filter((d) => d.isDirectory())) {
      const {index, sorted} = processDirectory(join(base, cat.name));
      totalIndex += index;
      totalSorted += sorted;
    }
  } else {
    const {index, sorted} = processDirectory(base);
    totalIndex += index;
    totalSorted += sorted;
  }
}

console.log(
  `fix-sidebar-order: ${totalIndex} index pages unlisted, ${totalSorted} docs sorted A–Z by title`,
);
